import math

def beam_search(step_fn, prompt, beam_width=3, max_new_tokens=10, eos_token_id=None):
    beams = [(list(prompt), 0.0, False)]
    for _ in range(max_new_tokens):
        candidates = []
        for tokens, score, finished in beams:
            if finished:
                candidates.append((tokens, score, True))
                continue
            log_probs = step_fn(tokens)
            for token_id, log_prob in log_probs:
                ended = eos_token_id is not None and token_id == eos_token_id
                candidates.append((tokens + [token_id], score + log_prob, ended))
        beams = sorted(candidates, key=lambda item: item[1], reverse=True)[:beam_width]
        if all(finished for _, _, finished in beams):
            break
    return max(beams, key=lambda item: item[1])[0]
